import{_ as a,o as e,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"架构与实战总览","description":"","frontmatter":{"title":"架构与实战总览"},"headers":[],"relativePath":"ts-ai/architecture/index.md","filePath":"ts-ai/architecture/index.md","lastUpdated":1786166505000}'),n={name:"ts-ai/architecture/index.md"};function i(d,t,o,l,h,g){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="架构与实战总览" tabindex="-1">架构与实战总览 <a class="header-anchor" href="#架构与实战总览" aria-label="Permalink to &quot;架构与实战总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>把前面各模块的能力收成<strong>可辩护的架构决策 + 一个可验收的贯穿项目 + 交付文档</strong>。本模块不是再开一套 API 课，也不要求做完所有项目。</p><p>前置：至少完成 <a href="/ts-ai/backend/">服务端</a>、<a href="/ts-ai/integration/">全栈集成</a> 主线，以及 <a href="/ts-ai/quality/">质量与生产</a> 的门禁与安全底线；按升级路径再补 RAG / 工作流。</p><p><strong>怎么读：</strong></p><ol><li>必学 <a href="/ts-ai/architecture/design-decisions/">架构与决策</a> 前三篇；网关 ADR / 选型 ADR 按需</li><li><strong>按目标</strong>读 0～1 篇 <a href="/ts-ai/architecture/agent-types/">Agent 类型</a>（不要通读；Research/Data-SQL 的项目实战由 P3/P4 承接）</li><li><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a>：<strong>必修基线项目</strong>，从 0 建造 7 章，章末勾验收 <strong>A1–A8</strong></li><li>边做边填 / 收尾时填 <a href="/ts-ai/architecture/delivery/">项目交付</a>（方法外链 quality）</li><li>最后用 <a href="/ts-ai/architecture/assembly/assembly-recipes-checklist">组装配方与自检</a> 收束</li></ol><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>你在学什么</th><th>优先级</th></tr></thead><tbody><tr><td><a href="/ts-ai/architecture/design-decisions/">架构与决策</a></td><td>全栈分层、框架边界、状态所有权；网关/ADR</td><td><strong>必学</strong>（后两篇按需）</td></tr><tr><td><a href="/ts-ai/architecture/agent-types/">Agent 类型</a></td><td>领域模式目录（含 Research/SQL，无对等项目篇）</td><td><strong>按需选读</strong>；部分扩展</td></tr><tr><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td><td><strong>从 0 建造</strong>必修基线项目：流式回答 + 分诊建工单 + 转人工</td><td><strong>主路径必做</strong></td></tr><tr><td><a href="/ts-ai/architecture/delivery/">项目交付</a></td><td>本项目验收与上线文档</td><td><strong>必学</strong>（针对所选项目）</td></tr><tr><td><a href="/ts-ai/architecture/assembly/assembly-recipes-checklist">组装配方与能力自检</a></td><td>选型配方与跨组勾选</td><td><strong>必学</strong>（模块末）</td></tr></tbody></table><h2 id="跨章所有权" tabindex="-1">跨章所有权 <a class="header-anchor" href="#跨章所有权" aria-label="Permalink to &quot;跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>框架职责边界</td><td>Nuxt / Nest / LangChain / LangGraph <strong>决策层</strong>边界</td><td>各框架 API → 对应模块</td></tr><tr><td>模型网关</td><td><strong>ADR</strong></td><td>Nest 实现 → backend；路由策略 → agent</td></tr><tr><td>前后端状态</td><td>UI / 事实 / Run / 持久所有权</td><td>协议 → integration；表模型 → backend</td></tr><tr><td>AI 客服中心</td><td><strong>项目级</strong>协议+鉴权+Chat 交付</td><td>协议/Composable 细节 → integration</td></tr><tr><td>后续项目 P2–P5</td><td><strong>规划与增量边界</strong>（本页 §后续项目实战规划；P2 正文在 <a href="/ts-ai/architecture/help-center-rag/">实战 · 帮助中心问答</a>）</td><td>RAG / 图 API → knowledge / workflow</td></tr><tr><td>Research / Data/SQL</td><td>模式在 <a href="/ts-ai/architecture/agent-types/">Agent 类型</a></td><td>项目实战由 P3 研究报告 / P4 数据分析承接；多模态等不单开项目篇</td></tr><tr><td>评测 / 威胁 / 发布</td><td><strong>本项目</strong>填写</td><td>方法 → quality；模板 → appendix</td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分层架构 → 框架边界 → 状态所有权</span></span>
<span class="line"><span>  →（按需）网关 ADR、选型 ADR、0～1 篇 Agent 类型</span></span>
<span class="line"><span>  → 实战 · AI 客服中心（必修基线，从 0 建造）</span></span>
<span class="line"><span>  → 填写项目交付六件套</span></span>
<span class="line"><span>  → P2 帮助中心问答 / P3 研究报告 / P4 数据分析（一次一个，从 P1 基线起步）</span></span>
<span class="line"><span>  →（可选）P5 内容审校流水线</span></span>
<span class="line"><span>  → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="后续项目实战规划-p2–p5" tabindex="-1">后续项目实战规划（P2–P5） <a class="header-anchor" href="#后续项目实战规划-p2–p5" aria-label="Permalink to &quot;后续项目实战规划（P2–P5）&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">规划占位</p><p>P2 正文已全部交付（收官）；P3–P5 为已定稿的路线大纲，章节正文待写。每个项目是<strong>独立产品形态</strong>，从 P1 基线成品起步；一次做一个，各自独立验收，可停在任一项目。</p></div><table tabindex="0"><thead><tr><th>#</th><th>项目</th><th>产品形态</th><th>技术重点</th><th>总验收模块</th><th>前置</th><th>状态</th></tr></thead><tbody><tr><td>P2</td><td>产品帮助中心问答（对外 RAG）</td><td>嵌入式组件 + 管理台</td><td>检索 / 引用 / 反馈闭环</td><td>knowledge</td><td>P1</td><td><strong>第 1–7 章正文已全部交付（P2 收官）</strong></td></tr><tr><td>P3</td><td>深度研究报告 Agent</td><td>异步任务 → 报告文档</td><td>长任务 Run / Interrupt / 检查点</td><td>workflow</td><td>P1</td><td>规划中</td></tr><tr><td>P4</td><td>经营数据分析 Agent（NL→SQL→图表）</td><td>数据看板</td><td>MCP 治理 / 结构化输出 / 护栏</td><td>tools-mcp + 结构化输出</td><td>P1</td><td>规划中</td></tr><tr><td>P5</td><td>多角色内容审校流水线</td><td>批处理流水线</td><td>Supervisor / 预算守卫 / 对照实验</td><td>multi-agent + 评测门禁</td><td>P1</td><td>规划中</td></tr></tbody></table><p>P2–P5 均沿用 P1 基线栈：pnpm workspace + NestJS 10 + Nuxt 3 + Vitest，版本以 <a href="/ts-ai/appendix/references/technology-stack-compatibility">技术栈与版本兼容表</a> 为准；各项目下面只列<strong>新增</strong>技术项（初步选型，写正文时再定稿）。</p><h3 id="p2-产品帮助中心问答-对外-rag" tabindex="-1">P2：产品帮助中心问答（对外 RAG） <a class="header-anchor" href="#p2-产品帮助中心问答-对外-rag" aria-label="Permalink to &quot;P2：产品帮助中心问答（对外 RAG）&quot;">​</a></h3><p>正文入口：<a href="/ts-ai/architecture/help-center-rag/">实战 · 帮助中心问答</a>（总览已定稿；第 1 章<a href="/ts-ai/architecture/help-center-rag/postgres-pgvector-migration">Postgres + pgvector 存储迁移</a>、第 2 章<a href="/ts-ai/architecture/help-center-rag/document-management-permissions">文档管理与权限</a>、第 3 章<a href="/ts-ai/architecture/help-center-rag/ingestion-parse-chunk-embed">Ingestion：解析、分块与嵌入</a>、第 4 章<a href="/ts-ai/architecture/help-center-rag/permission-hybrid-retrieval">权限检索与混合检索</a>、第 5 章<a href="/ts-ai/architecture/help-center-rag/rag-run-citations-refusal">RAG Run：拒答、引用与流式</a>、第 6 章<a href="/ts-ai/architecture/help-center-rag/widget-admin-ui">嵌入式组件与管理台 UI</a>、第 7 章<a href="/ts-ai/architecture/help-center-rag/feedback-loop-evaluation-gate">反馈闭环与评测门禁</a>全部交付，P2 收官）。</p><ul><li><strong>定位</strong>：取代旧「内部知识库」——对外场景、带反馈闭环，与 py-agent 的内部知识库错开</li><li><strong>与 P1 的关系</strong>：复用 Thread/Run/SSE/租户鉴权；用户从内部坐席换成外部访客，回答必须有依据</li><li><strong>技术栈（新增）</strong>：Postgres 16 + pgvector；Prisma 持久化与迁移；Embedding 走 Gateway（测试用 Fake Embedding）；混合检索（向量 + 全文）；嵌入式问答组件（Vue 3）+ 管理台（Nuxt 3）</li><li><strong>章节大纲</strong>：总览 → Postgres+pgvector 存储迁移 → 文档管理与权限 → Ingestion（解析 / 分块 / 嵌入）→ 权限检索与混合检索 → RAG Run（拒答 / 引用 / 流式）→ 嵌入式组件与管理台 UI → 反馈闭环与评测门禁</li><li><strong>验收核心</strong>：仅授权文档可召回；回答带引用；空检索不胡答；“是否有帮助”反馈回流评测</li></ul><h3 id="p3-深度研究报告-agent" tabindex="-1">P3：深度研究报告 Agent <a class="header-anchor" href="#p3-深度研究报告-agent" aria-label="Permalink to &quot;P3：深度研究报告 Agent&quot;">​</a></h3><ul><li><strong>定位</strong>：取代旧「售后执行」——HITL 用「大纲确认」承载，长任务 / 恢复照样验收；售后领域留给 py-agent</li><li><strong>与 P1 的关系</strong>：复用 Run/事件模型；Run 从对话轮次变为异步长任务，队列 + 检查点恢复</li><li><strong>技术栈（新增）</strong>：LangGraph.js（StateGraph + Postgres checkpointer）；Interrupt / Command 人机回路；任务队列初版用 Postgres jobs 表 + worker 循环（可选升级 BullMQ）；长任务事件复用 P1 SSE 总线；进度时间线与恢复面板（Nuxt 3）</li><li><strong>章节大纲</strong>：总览 → 研究计划与证据模型 → 任务队列与长时 Run → 大纲确认（Interrupt + HITL）→ 检查点图 → 报告生成与引用 → 进度与恢复 UI → 演练与验收</li><li><strong>验收核心</strong>：大纲确认后才继续生成；中断 / 重启后可恢复同一任务；报告引用可追溯；长任务状态可观察可取消</li></ul><h3 id="p4-经营数据分析-agent" tabindex="-1">P4：经营数据分析 Agent <a class="header-anchor" href="#p4-经营数据分析-agent" aria-label="Permalink to &quot;P4：经营数据分析 Agent&quot;">​</a></h3><ul><li><strong>定位</strong>：取代旧「纯 MCP 网关项目」——把数据工具做成 MCP Server 接入，MCP 治理（白名单 / 审计 / 超时）落到产品里教</li><li><strong>与 P1 的关系</strong>：复用 Model Gateway 与协议；加 NL→SQL 结构化输出与只读护栏</li><li><strong>技术栈（新增）</strong>：@modelcontextprotocol/sdk（自建两个只读数据 MCP Server）；Nest MCP 网关（发现 / 白名单 / 审计）；Zod 结构化输出（NL→SQL 校验）；SQLite / Postgres 只读沙箱数据；ECharts 看板（Nuxt 3）</li><li><strong>章节大纲</strong>：总览 → Schema 元数据与结构化输出 → 数据 MCP Server → Nest 网关治理（白名单 / 审计）→ NL→SQL→图表链路 → 看板 UI → 护栏演练与验收</li><li><strong>验收核心</strong>：SQL 只读；越权表查不到；结构化输出过校验；工具调用可审计；幻觉工具名硬拒绝</li></ul><h3 id="p5-多角色内容审校流水线-可选进阶" tabindex="-1">P5：多角色内容审校流水线（可选进阶） <a class="header-anchor" href="#p5-多角色内容审校流水线-可选进阶" aria-label="Permalink to &quot;P5：多角色内容审校流水线（可选进阶）&quot;">​</a></h3><ul><li><strong>定位</strong>：重定位为合规审校线（稿件 → 初审 → 复核 → 结论），不是“写营销稿”</li><li><strong>硬性要求</strong>：必须带单 Agent 基线 A/B 对照实验，无对照数据不得结项</li><li><strong>技术栈（新增）</strong>：LangGraph.js Supervisor / Handoff；token 预算守卫 middleware；Vitest + rubric 评测数据集门禁；批处理入口（CLI + 定时任务）；Fake Provider 基线 vs 可选真模型对照</li><li><strong>章节大纲</strong>：总览（何时才该上多角色 + 对照设计）→ 单角色审校基线 → Supervisor 审校图 → 共享状态与预算守卫 → 阶段事件与成本看板 → 对照实验与采纳门槛 → 验收归档</li></ul><p>Research / Data/SQL 已由 P3 / P4 承接；多模态等其他领域形态不单开项目，在 <a href="/ts-ai/architecture/agent-types/">Agent 类型</a> 以模式承接。</p><h2 id="主路径-全栈交付-而非领域换皮" tabindex="-1">主路径：全栈交付，而非领域换皮 <a class="header-anchor" href="#主路径-全栈交付-而非领域换皮" aria-label="Permalink to &quot;主路径：全栈交付，而非领域换皮&quot;">​</a></h2><p>本手册项目实战默认证明 <strong>TypeScript 全栈可交接</strong>，与 py-agent 的领域 Agent 项目互补：</p><ol><li><strong>AI 客服中心</strong>证协议、底座与可交接的全栈基线（P1 必修）</li><li><strong>P2 帮助中心问答 / P3 研究报告 / P4 数据分析</strong> 是三种独立产品形态，从 P1 基线起步，分别证知识、长任务、数据治理三条深路径（见上方规划）</li><li><strong>P5 内容审校流水线</strong>是可选进阶，仅在基线不够时启用，且必须带对照实验</li></ol>`,29)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
